/**
 * Chat-path API over a shared [`CoreSession`]. Every method is async and runs on the shared
 * runtime; failures throw `CoreError` (`.session(isAuth: true)` means re-login).
 */
public protocol CoreApiProtocol: AnyObject, Sendable {
    
    /**
     * Version counter from `archivedchat/list`.
     */
    func archivedVersion()  -> Int64
    
    func deleteMessageForMe(convId: String, msgId: String, cliMsgId: String, senderId: String) async throws 
    
    /**
     * `uid -> alias`.
     */
    func fetchAliases() async throws  -> [String: String]
    
    func fetchArchivedChats() async throws  -> [String]
    
    /**
     * One HTTP long-poll of the chat queue.
     */
    func fetchChatFromPolling(state: PollStateRecord) async throws  -> PollOutcomeRecord
    
    /**
     * Label data (`data` object of `convlabel/get`) as lossless JSON.
     */
    func fetchConversationLabels() async throws  -> String
    
    /**
     * Friends page: one lossless JSON object per friend.
     */
    func fetchFriends(page: Int64, count: Int64) async throws  -> [String]
    
    /**
     * `{gridVerMap, gridInfoMap}` as lossless JSON.
     */
    func fetchGroupsList() async throws  -> String
    
    func fetchHistory(convId: String, lastMsgId: String?, count: Int64, isOld: Bool?) async throws  -> HistoryRecord
    
    /**
     * Mute rows (`type` 1 = peer, 2 = group): one lossless JSON object each.
     */
    func fetchMuteList() async throws  -> [String]
    
    func fetchPinnedConversations() async throws  -> [String]
    
    /**
     * Recent threads with last messages (empty `thread_ids` = active-thread overview).
     */
    func fetchPreloadConversations(threadIds: [String]) async throws  -> String
    
    /**
     * `{"data": {"profiles": {uid: row}}}` as lossless JSON.
     */
    func fetchProfiles(uids: [String]) async throws  -> String
    
    /**
     * Version counter from `convlabel/get`.
     */
    func labelVersion()  -> Int64
    
    func recallMessage(convId: String, msgId: String, cliMsgId: String, isE2ee: Bool) async throws 
    
    /**
     * Sends a pre-built E2EE envelope. `list_params_json` holds one JSON object per entry
     * (`olaz_api::build_e2ee_list_param_entry` shape, built by the Signal layer in Swift).
     */
    func sendE2eeMessage(endpoint: String, threadId: String, isGroup: Bool, clientId: Int64, listParamsJson: [String], destType: Int64) async throws  -> SendResultRecord
    
    /**
     * Returns the client id used for the reaction.
     */
    func sendReaction(convId: String, msgId: String, cliMsgId: String, rIcon: String, rType: Int64, msgType: Int64, clientId: Int64?) async throws  -> Int64
    
    /**
     * Marks a message seen (errors are ignored, like Swift).
     */
    func sendSeen(convId: String, msgId: String, cliMsgId: String, senderId: String) async throws 
    
    func sendText(args: SendTextRecord) async throws  -> SendResultRecord
    
    /**
     * Fire-and-forget typing indicator (errors are ignored, like Swift).
     */
    func sendTyping(convId: String) async throws 
    
    func setUnreadMark(convId: String, unread: Bool) async throws 
    
}
