#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreStore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CoreStore

    public static func lift(_ handle: UInt64) throws -> CoreStore {
        return CoreStore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CoreStore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreStore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CoreStore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreStore_lift(_ handle: UInt64) throws -> CoreStore {
    return try FfiConverterTypeCoreStore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreStore_lower(_ value: CoreStore) -> UInt64 {
    return FfiConverterTypeCoreStore.lower(value)
}






/**
 * The server answer of a history call, parsed on demand. Ids stay exact (lossless JSON never leaves Rust).
 */
public protocol HistoryBatchProtocol: AnyObject, Sendable {
    
    /**
     * Every message and live reaction / recall / delete in the answer, parsed with `options` (`extractBatchEvents`).
     * Synchronous and CPU-bound: call it off the main actor for big pages.
     */
    func events(myUid: String, options: WireOptions)  -> [WireEvent]
    
    /**
     * The answer as lossless JSON text, for the few callers that read raw fields (cloud-message lookups, audits).
     */
    func rawJson()  -> String
    
}
/**
 * The server answer of a history call, parsed on demand. Ids stay exact (lossless JSON never leaves Rust).
 */
open class HistoryBatch: HistoryBatchProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
