public enum AvailabilityRecord: Equatable, Hashable {
    
    case hidden
    case available
    case blocked





}

#if compiler(>=6)
extension AvailabilityRecord: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAvailabilityRecord: FfiConverterRustBuffer {
    typealias SwiftType = AvailabilityRecord

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AvailabilityRecord {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .hidden
        
        case 2: return .available
        
        case 3: return .blocked
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AvailabilityRecord, into buf: inout [UInt8]) {
        switch value {
        
        
        case .hidden:
            writeInt(&buf, Int32(1))
        
        
        case .available:
            writeInt(&buf, Int32(2))
        
        
        case .blocked:
            writeInt(&buf, Int32(3))
        
        }
    }
}


