     * DoH answered NXDOMAIN (Swift `DoHResolver.ResolveError.notFound`).
     */
    case DohNotFound
    /**
     * Every DoH endpoint failed (Swift `ResolveError.allEndpointsFailed`).
     */
    case DohAllFailed
    case Net(kind: MediaNetKind
    )
